CREATE TABLE IF NOT EXISTS app_fila_novedades( id BIGSERIAL PRIMARY KEY, origen_tipo TEXT NOT NULL DEFAULT 'hoja', file_id BIGINT NULL, sheet_id BIGINT NULL, row_number BIGINT NULL, expediente_id BIGINT NULL REFERENCES expedientes( id) ON DELETE SET NULL, suspension_id BIGINT NULL REFERENCES expediente_suspensiones( id) ON DELETE SET NULL, credencial TEXT NULL, nombre_agente TEXT NULL, numero_expediente TEXT NULL, tipo_novedad TEXT NOT NULL DEFAULT 'Observación de fila', fecha_evento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, titulo TEXT NOT NULL, descripcion TEXT NOT NULL, observaciones TEXT NULL, campos_editados_json JSONB NOT NULL DEFAULT '{}'::jsonb, usuario TEXT NOT NULL, user_id BIGINT NULL REFERENCES app_users( id) ON DELETE SET NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ; CREATE INDEX IF NOT EXISTS idx_fila_nov_sheet_row ON app_fila_novedades( sheet_id, row_number) ; CREATE INDEX IF NOT EXISTS idx_fila_nov_exp ON app_fila_novedades( expediente_id) ; CREATE INDEX IF NOT EXISTS idx_fila_nov_cred ON app_fila_novedades( credencial) ; CREATE INDEX IF NOT EXISTS idx_expedientes_num_upper ON expedientes( UPPER( TRIM( numero_expediente) ) ) ; CREATE INDEX IF NOT EXISTS idx_exp_agentes_cred_upper ON expediente_agentes( UPPER( TRIM( credencial) ) ) ; CREATE INDEX IF NOT EXISTS idx_personas_cred_upper ON personas( UPPER( TRIM( credencial) ) ) ; CREATE INDEX IF NOT EXISTS idx_suspensiones_cred_upper ON expediente_suspensiones( UPPER( TRIM( credencial) ) ) ; 